WITH lines AS (SELECT id, customer_id, created_at, item.product_id, item.qty, item.price, item.promo FROM carts LATERAL VIEW EXPLODE(items) x AS item) SELECT CASE WHEN product_id >= 9 THEN 'LARGE' ELSE 'SMALL' END AS product_id_tier, CASE WHEN qty >= 4 THEN 'PREMIUM' ELSE 'STANDARD' END AS qty_tier, COUNT(DISTINCT id) AS distinct_ids, MIN(created_at) AS started_at, SIZE(COLLECT_SET(promo)) AS num_promos FROM lines GROUP BY CASE WHEN product_id >= 9 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN qty >= 4 THEN 'PREMIUM' ELSE 'STANDARD' END;
